// === Zentrale Konfiguration – hier pflegen ===
const CONFIG = {
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',

  // Zeitraum in UTC. 01.08.2026 00:00 MESZ = 31.07.2026 22:00 UTC
  createdAtMin: '2026-07-31T22:00:00Z',
  createdAtMax: null,   // null = bis jetzt

  // Gesuchte Position
  zielSku: 'ZB-2026-08-02',

  // true = Position zählt auch, wenn sie inzwischen entfernt/refundiert wurde
  zielSkuAuchEntfernt: true,

  // --- Rabatt-Erkennung ---
  // Belegt durch den Roh-Dump: discount_codes ist bei Abo-Bestellungen LEER.
  // Appstle-Abo-Rabatte melden sich in discount_applications als type "manual",
  // der Codename steht nur in title/description. Kriterium ist deshalb die
  // Rabatt-Allokation auf der Ziel-Position, nicht discount_codes.
  nurRabattAufZielSku: true,      // true = Rabatt muss auf ZB-2026-08-02 gebucht sein
  versandrabatteZaehlen: false,   // true = auch target_type "shipping_line" (Gratisversand)
  mindestRabattBetrag: 0.01,      // 0 = auch 0,00-Rabatte

  // fields-Whitelist. false = alle Order-Felder holen (wie im Roh-Dump verifiziert).
  fieldsFilterNutzen: false,

  // Optionaler Länderfilter, z.B. ['DE']. null = alle Länder.
  nurLaender: null,

  // Einzelne Bestellungen ausschließen ('BB-12345' oder orderId). [] = keine.
  ausnahmen: []
};

const staticData = $getWorkflowStaticData('global');
staticData.config = CONFIG;
staticData.found = [];
staticData.skipped = [];
staticData.scanned = 0;
staticData.stats = null;

return [{ json: { config: CONFIG } }];

const config = $('Config').first().json.config;
const shop = config.shop;

let initUrl = `https://${shop}.myshopify.com/admin/api/${config.apiVersion}/orders.json`
  + `?limit=250`
  + `&status=any`
  + `&order=${encodeURIComponent('created_at asc')}`
  + `&created_at_min=${encodeURIComponent(config.createdAtMin)}`;

// Ohne fields-Parameter liefert Shopify alle Order-Felder – im Roh-Dump verifiziert.
if (config.fieldsFilterNutzen === true) {
  initUrl += `&fields=id,name,created_at,currency,presentment_currency,financial_status,tags,total_price,total_discounts,discount_codes,discount_applications,line_items,shipping_address`;
}

if (config.createdAtMax) {
  initUrl += `&created_at_max=${encodeURIComponent(config.createdAtMax)}`;
}

const staticData = $getWorkflowStaticData('global');
staticData.found = [];
staticData.skipped = [];
staticData.scanned = 0;
staticData.stats = null;

return [{
  json: {
    nextUrl: initUrl,
    hasNext: true,
    accessToken: $('Token holen').first().json.access_token
  }
}];

const response = $input.first().json;
const orders = response.body?.orders || response.orders || [];
const headers = response.headers || {};

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.found)) staticData.found = [];
if (!Array.isArray(staticData.skipped)) staticData.skipped = [];
staticData.scanned = (staticData.scanned || 0) + orders.length;

const ZIEL_SKU = String(config.zielSku).trim().toLowerCase();
const num = (v) => Number(v || 0);

const stats = staticData.stats || (staticData.stats = {
  bestellungenGeprueft: 0,
  mitZielSku: 0,
  mitRabattIrgendwo: 0,
  mitRabattAufZielSku: 0,
  nurVersandrabatt: 0,
  ausgeschlossenDurchMindestbetrag: 0,
  gutscheinNamen: {}
});
stats.bestellungenGeprueft += orders.length;

// Ausnahmeliste normalisieren: 'BB-12345', '#BB-12345' und 12345 matchen gleich
const norm = (v) => String(v ?? '').trim().replace(/^#/, '').toLowerCase();
const AUSNAHMEN = (Array.isArray(config.ausnahmen) ? config.ausnahmen : []).map(norm);

// Name eines Rabatts: bei "manual"/Abo steckt der Code nur in title/description
const appName = (a) => a?.code || a?.title || a?.description || '(ohne Titel)';

for (const order of orders) {
  const lineItems = order.line_items || [];
  const aktive = lineItems.filter(li => num(li.current_quantity) > 0);
  const basis = config.zielSkuAuchEntfernt === true ? lineItems : aktive;
  const zielPositionen = basis.filter(li => String(li.sku || '').trim().toLowerCase() === ZIEL_SKU);

  // Bedingung 1: Ziel-SKU enthalten
  if (!zielPositionen.length) continue;
  stats.mitZielSku++;

  const codes = Array.isArray(order.discount_codes) ? order.discount_codes : [];
  const apps  = Array.isArray(order.discount_applications) ? order.discount_applications : [];

  // Versandrabatte optional ausblenden
  const relevanteApps = apps.filter(a =>
    config.versandrabatteZaehlen === true || String(a.target_type || '') !== 'shipping_line');

  // Rabattsumme, die konkret auf den Ziel-Positionen gebucht ist,
  // plus Zuordnung Allokation -> discount_application (über den Index)
  const zielAppIndizes = new Set();
  let zielRabatt = 0;
  for (const li of zielPositionen) {
    for (const alloc of (li.discount_allocations || [])) {
      const betrag = num(alloc.amount);
      if (betrag <= 0) continue;
      const idx = Number(alloc.discount_application_index);
      if (!Number.isNaN(idx)) {
        if (!config.versandrabatteZaehlen && String(apps[idx]?.target_type || '') === 'shipping_line') continue;
        zielAppIndizes.add(idx);
      }
      zielRabatt += betrag;
    }
  }

  const rabattIrgendwo = relevanteApps.length > 0 || num(order.total_discounts) > 0;
  if (rabattIrgendwo) stats.mitRabattIrgendwo++;
  if (apps.length && !relevanteApps.length) stats.nurVersandrabatt++;

  // Bedingung 2: Rabatt vorhanden
  const hatRabatt = config.nurRabattAufZielSku === true ? zielRabatt > 0 : rabattIrgendwo;
  if (!hatRabatt) continue;
  stats.mitRabattAufZielSku++;

  // Bedingung 3: Mindestbetrag – bezogen auf das gewählte Kriterium
  const pruefBetrag = config.nurRabattAufZielSku === true ? zielRabatt : num(order.total_discounts);
  if (config.mindestRabattBetrag != null && pruefBetrag < Number(config.mindestRabattBetrag)) {
    stats.ausgeschlossenDurchMindestbetrag++;
    continue;
  }

  // Rabatte, die auf der Ziel-Position gelandet sind
  const zielApps = [...zielAppIndizes].map(i => apps[i]).filter(Boolean);
  for (const a of (zielApps.length ? zielApps : relevanteApps)) {
    const n = appName(a);
    stats.gutscheinNamen[n] = (stats.gutscheinNamen[n] || 0) + 1;
  }

  const fmtApp = (a) => `${appName(a)} (${a.value}${a.value_type === 'percentage' ? '%' : ''}, ${a.type})`;

  const datensatz = {
    orderId: order.id,
    orderName: order.name,
    createdAt: order.created_at,
    currency: order.presentment_currency || order.currency,
    financialStatus: order.financial_status || null,
    quelle: order.source_name || null,
    land: order.shipping_address?.country_code || order.billing_address?.country_code || null,
    totalPrice: order.total_price,
    totalDiscounts: order.total_discounts,

    // Rabatt auf der Ziel-Position – das eigentliche Suchkriterium
    rabattAufZielSku: zielRabatt.toFixed(2),
    gutscheinAufZielSku: zielApps.map(appName).join(', '),
    gutscheinAufZielSkuDetail: zielApps.map(fmtApp).join(' | '),
    rabattTypen: zielApps.map(a => a.type).join(', '),

    // Alle Rabatte der Bestellung (Kontext)
    alleRabatte: relevanteApps.map(fmtApp).join(' | '),
    echteGutscheincodes: codes.map(c => c.code).join(', '),

    zielSkuMenge: zielPositionen.reduce((s, li) => s + num(li.current_quantity), 0),
    zielSkuMengeBestellt: zielPositionen.reduce((s, li) => s + num(li.quantity), 0),
    zielSkuEntfernt: zielPositionen.every(li => num(li.current_quantity) === 0),

    rabatte: relevanteApps.map(a => ({
      name: appName(a), typ: a.type, wert: a.value, wertTyp: a.value_type,
      ziel: a.target_type, auswahl: a.target_selection, methode: a.allocation_method
    })),
    positionen: zielPositionen.map(li => ({
      lineItemId: li.id,
      title: li.title,
      variantId: li.variant_id,
      sku: li.sku,
      preis: li.price,
      quantity: li.quantity,
      currentQuantity: li.current_quantity,
      entfernt: num(li.current_quantity) === 0,
      rabattAllokationen: (li.discount_allocations || []).map(a => a.amount)
    })),
    tags: order.tags || ''
  };

  if (AUSNAHMEN.length && (AUSNAHMEN.includes(norm(order.name)) || AUSNAHMEN.includes(norm(order.id)))) {
    staticData.skipped.push({ ...datensatz, grund: 'Bestellung steht in Config.ausnahmen' });
    continue;
  }

  if (Array.isArray(config.nurLaender) && !config.nurLaender.includes(datensatz.land)) {
    staticData.skipped.push({ ...datensatz, grund: 'Land ' + datensatz.land + ' nicht in Config.nurLaender' });
    continue;
  }

  staticData.found.push(datensatz);
}

// Cursor-Pagination über Link-Header (rel="next")
const linkHeader = String(headers.link || headers.Link || '');
let nextUrl = null;
const nextPart = linkHeader.split(',').find(p => p.includes('rel="next"'));
if (nextPart) {
  const m = nextPart.match(/<([^>]+)>/);
  if (m) nextUrl = m[1];
}

return [{
  json: {
    nextUrl: nextUrl,
    hasNext: !!nextUrl,
    scannedCount: staticData.scanned,
    foundCount: staticData.found.length,
    skippedCount: staticData.skipped.length
  }
}];

const tokenItem = $input.first().json;
const urlItem = $input.last().json;

return [{
  json: {
    accessToken: tokenItem.access_token,
    nextUrl: urlItem.nextUrl,
    hasNext: urlItem.hasNext
  }
}];

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const found = staticData.found || [];

if (!found.length) {
  return [{
    json: {
      hinweis: 'Keine Bestellung mit ' + config.zielSku + ' + Gutschein im Zeitraum gefunden',
      zielSku: config.zielSku,
      zeitraumVon: config.createdAtMin,
      zeitraumBis: config.createdAtMax || 'jetzt',
      geprüfteBestellungen: staticData.scanned || 0
    }
  }];
}

// nach Datum sortieren
found.sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));

return found.map(o => ({ json: o }));

const staticData = $getWorkflowStaticData('global');
const skipped = staticData.skipped || [];
if (!skipped.length) return [{ json: { hinweis: 'Keine übersprungenen Bestellungen' } }];
return skipped.map(o => ({ json: o }));

// Nur flache Felder für die CSV – verschachtelte Objekte würden [object Object] erzeugen
const items = $input.all();

if (items.length === 1 && items[0].json.hinweis) {
  return [{ json: { hinweis: items[0].json.hinweis, geprüfteBestellungen: items[0].json.geprüfteBestellungen } }];
}

const datum = (iso) => {
  if (!iso) return '';
  return new Date(iso).toLocaleString('de-DE', {
    timeZone: 'Europe/Berlin',
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  });
};

return items.map(i => {
  const o = i.json;
  return {
    json: {
      Bestellnummer: o.orderName,
      OrderId: o.orderId,
      Bestelldatum: datum(o.createdAt),
      Quelle: o.quelle,
      Land: o.land,
      Waehrung: o.currency,
      Zahlungsstatus: o.financialStatus,
      Bestellwert: o.totalPrice,
      RabattGesamt: o.totalDiscounts,
      RabattAufZielSku: o.rabattAufZielSku,
      Gutschein: o.gutscheinAufZielSku,
      GutscheinDetail: o.gutscheinAufZielSkuDetail,
      RabattTyp: o.rabattTypen,
      AlleRabatte: o.alleRabatte,
      EchteGutscheincodes: o.echteGutscheincodes,
      MengeZielSku: o.zielSkuMenge,
      MengeZielSkuBestellt: o.zielSkuMengeBestellt,
      ZielSkuEntfernt: o.zielSkuEntfernt ? 'ja' : 'nein',
      LineItemIds: (o.positionen || []).map(p => p.lineItemId).join(', '),
      Tags: o.tags
    }
  };
});

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const s = staticData.stats || {};

const namen = Object.entries(s.gutscheinNamen || {})
  .sort((a, b) => b[1] - a[1])
  .map(([n, c]) => `${n} (${c})`);

return [{
  json: {
    zielSku: config.zielSku,
    zeitraumVon: config.createdAtMin,
    zeitraumBis: config.createdAtMax || 'jetzt',
    kriterium: config.nurRabattAufZielSku ? 'Rabatt auf Ziel-Position gebucht' : 'Rabatt irgendwo in der Bestellung',
    versandrabatteZaehlen: config.versandrabatteZaehlen,
    mindestRabattBetrag: config.mindestRabattBetrag,
    '---': '--- Ergebnis ---',
    bestellungenGeprueft: s.bestellungenGeprueft || 0,
    mitZielSku: s.mitZielSku || 0,
    mitRabattIrgendwo: s.mitRabattIrgendwo || 0,
    mitRabattNachKriterium: s.mitRabattAufZielSku || 0,
    nurVersandrabatt: s.nurVersandrabatt || 0,
    ausgeschlossenDurchMindestbetrag: s.ausgeschlossenDurchMindestbetrag || 0,
    treffer: (staticData.found || []).length,
    uebersprungen: (staticData.skipped || []).length,
    '----': '--- Gutscheine ---',
    gutscheinNamen: namen
  }
}];
